queryParts.push('sortAscending=false');
queryParts.push('page=1');

// Helper function to process and add array parameters to queryParts
const addArrayParams = (paramName, values) => {
  values.forEach(val => {
    // Replace '+' with space then encode the value 
    // (e.g., "sydney+australia" -> "sydney australia" -> "sydney%20australia")
    const decodedValue = val.replace(/\+/g, ' ');
    queryParts.push(`${paramName}[]=${encodeURIComponent(decodedValue)}`);
  });
};

// Process locations (maps to personLocations[])
